<template><div v-for='p in peers' :key='p.clientId' :style='{position:"absolute", left:(p.cursor?.x||0)+"px", top:(p.cursor?.y||0)+"px", transform:"translate(-50%, -50%)", pointerEvents:"none"}'><div style='display:flex;align-items:center;gap:6px;'><div style='width:8px;height:8px;border-radius:50%;background:#2a7;'></div><span style='background:#fff;padding:2px 6px;border:1px solid #ddd;border-radius:6px;font-size:12px;'>{{ p.name || ('Guest '+p.clientId) }}</span></div></div></template><script setup lang='ts'>import { onMounted, onUnmounted, ref } from 'vue'; const peers=ref<any[]>([]); let awareness:any; function updatePeers(){ if(!awareness) return; const states=Array.from(awareness.getStates().entries()).map(([clientId,s]:any)=>({clientId,...s})); peers.value=states; } onMounted(()=>{ awareness=(window as any).__awareness; if(awareness){ awareness.on('change', updatePeers); updatePeers(); } }); onUnmounted(()=>{ awareness?.off('change', updatePeers); });</script>